import "strings"

type Command struct {
	Indent int
	Flat   bool
	Doc    *Doc
}

func pushChildren(stack []Command, c Command) []Command {
	for j := len(c.Doc.Children) - 1; j >= 0; j-- {
		stack = append(stack, Command{c.Indent, c.Flat, c.Doc.Children[j]})
	}
	return stack
}
func fits(remaining int, first Command, original []Command) bool {
	if remaining < 0 {
		return false
	}
	stack := []Command{first}
	unused := len(original) - 1
	for len(stack) > 0 || unused >= 0 {
		if len(stack) == 0 {
			stack = append(stack, original[unused])
			unused--
		}
		c := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		d := c.Doc
		switch d.Kind {
		case "text":
			remaining -= len(d.Text)
		case "if_break":
			value := d.Text
			if c.Flat {
				value = d.Other
			}
			remaining -= len(value)
		case "line":
			if !c.Flat {
				return true
			}
			remaining--
		case "softline":
			if !c.Flat {
				return true
			}
		case "hardline":
			return true
		case "concat":
			stack = pushChildren(stack, c)
		case "group":
			flat := c.Flat
			if d.Forced {
				flat = false
			}
			stack = append(stack, Command{c.Indent, flat, d.Children[0]})
		case "nest", "align":
			stack = append(stack, Command{c.Indent, c.Flat, d.Children[0]})
		}
		if remaining < 0 {
			return false
		}
	}
	return true
}
func printDoc(doc *Doc, width, commentColumn int) []string {
	lines := []string{}
	current := ""
	column := 0
	pending := []string{}
	stack := []Command{{0, false, doc}}
	finalize := func() {
		line := strings.TrimRight(current, " ")
		if len(pending) > 0 {
			comments := strings.Join(pending, " ")
			if commentColumn > 0 && len(line) < commentColumn-1 && commentColumn-1+len(comments) <= width {
				line += strings.Repeat(" ", commentColumn-1-len(line)) + comments
			} else {
				line += " " + comments
			}
		}
		pending = nil
		lines = append(lines, line)
	}
	for len(stack) > 0 {
		c := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		d := c.Doc
		newline := false
		switch d.Kind {
		case "text":
			current += d.Text
			column += len(d.Text)
		case "if_break":
			value := d.Text
			if c.Flat {
				value = d.Other
			}
			current += value
			column += len(value)
		case "line":
			if c.Flat {
				current += " "
				column++
			} else {
				newline = true
			}
		case "softline":
			newline = !c.Flat
		case "hardline":
			newline = true
		case "concat":
			stack = pushChildren(stack, c)
		case "nest":
			stack = append(stack, Command{c.Indent + d.Number, c.Flat, d.Children[0]})
		case "align":
			stack = append(stack, Command{column, c.Flat, d.Children[0]})
		case "suffix":
			pending = append(pending, d.Text)
		case "group":
			mode := "flat"
			flat := true
			if !c.Flat {
				if d.Forced {
					mode = "forced"
					flat = false
				} else if !fits(width-column, Command{c.Indent, true, d.Children[0]}, stack) {
					mode = "break"
					flat = false
				}
			}
			d.Mode = mode
			stack = append(stack, Command{c.Indent, flat, d.Children[0]})
		}
		if newline {
			finalize()
			current = strings.Repeat(" ", c.Indent)
			column = c.Indent
		}
	}
	finalize()
	return lines
}

package main

import (
	"fmt"
	"strings"
)

func docTree(d *Doc, depth int) []string {
	prefix := strings.Repeat(" ", 2*depth)
	out := []string{}
	switch d.Kind {
	case "text", "suffix":
		out = append(out, prefix+d.Kind+` "`+d.Text+`"`)
	case "if_break":
		out = append(out, prefix+`if_break "`+d.Text+`" "`+d.Other+`"`)
	case "line", "softline", "hardline", "break_parent":
		out = append(out, prefix+d.Kind)
	case "concat":
		for _, child := range d.Children {
			out = append(out, docTree(child, depth)...)
		}
	case "group", "nest", "align":
		label := d.Kind
		if d.Kind == "group" {
			label += " " + d.Mode
		}
		if d.Kind == "nest" {
			label += fmt.Sprintf(" %d", d.Number)
		}
		out = append(out, prefix+label)
		out = append(out, docTree(d.Children[0], depth+1)...)
	}
	return out
}

type DiffOp struct {
	Delete bool
	Line   string
}
type Hunk struct {
	Old, New, Deletes, Inserts int
	Operations                 []DiffOp
}

func diffLines(a, b []string) ([]string, int, int) {
	n, m := len(a), len(b)
	lcs := make([][]int, n+1)
	for i := range lcs {
		lcs[i] = make([]int, m+1)
	}
	for i := n - 1; i >= 0; i-- {
		for j := m - 1; j >= 0; j-- {
			if a[i] == b[j] {
				lcs[i][j] = lcs[i+1][j+1] + 1
			} else {
				lcs[i][j] = max(lcs[i+1][j], lcs[i][j+1])
			}
		}
	}
	hunks := []Hunk{}
	i, j := 0, 0
	deletes, inserts := 0, 0
	for i < n || j < m {
		if i < n && j < m && a[i] == b[j] {
			i++
			j++
			continue
		}
		h := Hunk{Old: i, New: j}
		for (i < n || j < m) && !(i < n && j < m && a[i] == b[j]) {
			if j == m || i < n && lcs[i+1][j] >= lcs[i][j+1] {
				h.Operations = append(h.Operations, DiffOp{true, a[i]})
				h.Deletes++
				i++
			} else {
				h.Operations = append(h.Operations, DiffOp{false, b[j]})
				h.Inserts++
				j++
			}
		}
		deletes += h.Deletes
		inserts += h.Inserts
		hunks = append(hunks, h)
	}
	out := []string{fmt.Sprintf("hunks=%d deleted=%d inserted=%d", len(hunks), deletes, inserts)}
	for _, h := range hunks {
		a, b := h.Old, h.New
		if h.Deletes > 0 {
			a++
		}
		if h.Inserts > 0 {
			b++
		}
		out = append(out, fmt.Sprintf("@@ -%d,%d +%d,%d @@", a, h.Deletes, b, h.Inserts))
		for _, op := range h.Operations {
			prefix := "+"
			if op.Delete {
				prefix = "-"
			}
			out = append(out, prefix+op.Line)
		}
	}
	return out, deletes, inserts
}
